window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[119]={"id":"119","numero":119,"titre":"Soins et accompagnement dans la maladie chronique et le handicap","objectifs":[{"id":"119-1","rang":"A","rubrique":"Définition","titre":"Personnes vivant avec une maladie chronique et/ou en situation de handicap et leurs aidants : connaître l'expérience, le vécu et les savoirs expérientiels","contenu":"<p>Objectif <span class=\"kw-def\">transversal</span> qui invite à comprendre la maladie du <strong>point de vue de la personne</strong> : au-delà des chiffres et des traitements, le <span class=\"kw-def\">vécu</span>, l'<span class=\"kw-def\">expérience</span> et <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-def\">savoirs expérientiels</span></strong> du patient et de ses <span class=\"kw-def\">aidants</span> sont une composante à part entière du soin.</p>\n\n      <table >\n        <thead><tr><th>Notion</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Maladie chronique</strong></td>\n            <td><span class=\"kw-def\">Affection évoluant sur une longue durée</span> (souvent <span class=\"kw-chiffre\">&gt; 6 mois</span>), <span class=\"kw-def\">non spontanément résolutive</span>, avec <span class=\"kw-clinique\">retentissement sur la vie quotidienne</span> et nécessité d'une <span class=\"kw-def\">prise en charge prolongée</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Handicap</strong> <span class=\"kw-def\">(loi du 11 février 2005)</span></td>\n            <td><span class=\"kw-def\">Limitation d'activité</span> ou <span class=\"kw-def\">restriction de participation</span> à la vie en société, subie dans son environnement en raison d'une <span class=\"kw-etio\">altération durable d'une ou plusieurs fonctions</span> (physique, sensorielle, mentale, cognitive, psychique) ou d'un trouble de santé invalidant.</td>\n          </tr>\n          <tr>\n            <td><strong>Modèle de la CIF</strong> <span class=\"kw-def\">(OMS 2001)</span></td>\n            <td>Modèle <strong><span class=\"kw-def\">bio-psycho-social</span></strong> : <span class=\"kw-def\">déficience</span> (organe) → <span class=\"kw-def\">limitation d'activité</span> (personne) → <span class=\"kw-def\">restriction de participation</span> (société), en interaction avec <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">facteurs personnels</span> et <span class=\"kw-etio\">environnementaux</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Aidant</strong> (proche aidant)</td>\n            <td><span class=\"kw-def\">Personne non professionnelle</span> qui vient en aide de façon régulière à un proche en perte d'autonomie ou en situation de handicap, pour <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">activités de la vie quotidienne</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Vécu et expérience de la maladie</strong></p>\n      <ul>\n        <li>L'<span class=\"kw-def\">annonce</span> ouvre un <span class=\"kw-def\">travail de deuil</span> de l'état de santé antérieur et un <span class=\"kw-clinique\">bouleversement identitaire</span>.</li>\n        <li><strong><span class=\"kw-def\">Fardeau du traitement</span></strong> (« burden of treatment ») : poids des soins, contraintes et organisation du quotidien.</li>\n        <li>Retentissement sur la <span class=\"kw-def\">qualité de vie</span> et la vie <span class=\"kw-clinique\">familiale, sociale et professionnelle</span> ; risque d'<span class=\"kw-clinique\">isolement</span>.</li>\n        <li>Trajectoire faite de phases d'<span class=\"kw-clinique\">équilibre</span>, de <span class=\"kw-clinique\">crises</span> et d'<span class=\"kw-clinique\">aggravation</span>.</li>\n      </ul>\n\n      <p><strong>Savoirs expérientiels &amp; patient partenaire</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Savoir expérientiel</span></strong> = connaissance <span class=\"kw-etio\">acquise</span> par la personne du fait de <span class=\"kw-def\">vivre avec sa maladie</span> au quotidien (expertise « profane »), complémentaire du savoir médical.</li>\n        <li><span class=\"kw-def\">Patient partenaire</span> / <span class=\"kw-def\">patient-expert</span> : reconnaissance de cette expertise et <span class=\"kw-def\">co-construction</span> des décisions de soin.</li>\n        <li>S'inscrit dans la <strong><span class=\"kw-def\">démocratie sanitaire</span></strong> (droits des usagers) : <span class=\"kw-def\">associations de patients</span>, <span class=\"kw-def\">pair-aidance</span>.</li>\n        <li>Socle de l'<strong><span class=\"kw-def\">éducation thérapeutique</span></strong> (<span class=\"kw-def\">ETP</span>).</li>\n      </ul>\n\n      <p><strong>Place des aidants</strong></p>\n      <ul>\n        <li>Rôle <span class=\"kw-def\">central</span>, en particulier auprès de l'<span class=\"kw-clinique\">enfant</span> et de la personne très dépendante.</li>\n        <li><strong><span class=\"kw-alerte\">Fardeau de l'aidant</span></strong> : <span class=\"kw-clinique\">épuisement</span>, retentissement sur sa propre santé, sa vie sociale et financière.</li>\n        <li>Besoins de <span class=\"kw-def\">répit</span>, de <span class=\"kw-def\">soutien</span> et de <span class=\"kw-def\">reconnaissance</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Le handicap se définit par l'<span class=\"kw-def\">interaction</span> personne ↔ environnement (modèle bio-psycho-social), pas par la seule <span class=\"kw-clinique\">lésion</span> : deux personnes ayant la même <span class=\"kw-def\">déficience</span> peuvent vivre un handicap très différent selon leur environnement.\n      </div>\n\n      <p class=\"obj-source\"><em>Objectif sans contenu dans la fiche source Notion (stub) ; complété depuis <span class=\"kw-clinique\">les</span> Collèges de MPR (7ᵉ éd. — CIF &amp; item 118) et de Santé publique.</em></p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 118 — Personne handicapé · 56 — Enfant handicapé · 121 — Handicap psychique · 133 — Autonomie-dépendance du sujet âgé · 140 — Soins palliatifs 2 - accompagnement de la personne et de son entourage</em></p>","frequence":0},{"id":"119-2","rang":"B","rubrique":"Prise en charge","titre":"Intégrer dans la pratique médicale les connaissances transversales sur les objectifs, les valeurs et les difficultés, du travail de soin et d'accompagnement du patient","contenu":"<p>Au-delà de la technique, le <span class=\"kw-def\">soin</span> et l'<span class=\"kw-def\">accompagnement</span> dans la chronicité reposent sur des <strong><span class=\"kw-def\">objectifs</span></strong>, des <strong><span class=\"kw-def\">valeurs</span></strong> et la reconnaissance de <strong><span class=\"kw-def\">difficultés</span></strong> propres — à intégrer dans la pratique médicale courante.</p>\n\n      <p><strong>Objectifs du soin dans la chronicité</strong> (≠ modèle aigu curatif)</p>\n      <ul>\n        <li>Non plus la <span class=\"kw-def\">guérison</span>, mais le <strong><span class=\"kw-def\">maintien de la qualité de vie</span></strong>, l'<span class=\"kw-def\">autonomie</span> et la <span class=\"kw-def\">participation sociale</span>.</li>\n        <li><span class=\"kw-def\">Prévention des complications</span> et des décompensations.</li>\n        <li>Construction d'un <strong><span class=\"kw-def\">projet de soin individualisé</span></strong> articulé au <span class=\"kw-def\">projet de vie</span> (4 niveaux CIF : réduire la <span class=\"kw-def\">déficience</span>, la <span class=\"kw-def\">limitation d'activité</span>, prévenir <span class=\"kw-clinique\">les</span> complications, garantir la <span class=\"kw-def\">participation</span>).</li>\n      </ul>\n\n      <p><strong>Valeurs du soin et de l'accompagnement</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Alliance thérapeutique</span></strong> et relation de confiance inscrite dans la durée.</li>\n        <li><strong><span class=\"kw-def\">Décision médicale partagée</span></strong> : respect de l'<span class=\"kw-def\">autonomie</span> et des préférences du patient.</li>\n        <li><span class=\"kw-def\">Approche centrée sur la personne</span> (et non sur la seule maladie) ; <span class=\"kw-def\">dignité</span>, écoute, <span class=\"kw-def\">éthique du « care »</span>.</li>\n        <li>Prise en compte des <span class=\"kw-etio\">inégalités sociales de santé</span> et de la <span class=\"kw-etio\">précarité</span>.</li>\n      </ul>\n\n      <p><strong>Difficultés du travail de soin</strong></p>\n      <ul>\n        <li>Temps long et <span class=\"kw-clinique\">incertitude pronostique</span>.</li>\n        <li><strong><span class=\"kw-def\">Adhésion / observance</span></strong> mises à l'épreuve par le poids des contraintes.</li>\n        <li><span class=\"kw-alerte\">Épuisement</span> du patient, de l'<span class=\"kw-alerte\">aidant</span> et du <span class=\"kw-alerte\">soignant</span> (burn-out).</li>\n        <li>Complexité de la <span class=\"kw-def\">coordination pluriprofessionnelle</span> et des <span class=\"kw-clinique\">transitions</span> (ville ↔ hôpital, pédiatrie → adulte).</li>\n      </ul>\n\n      <p><strong>Leviers à mobiliser dans la pratique</strong> (détaillés dans <span class=\"kw-clinique\">les</span> items dédiés)</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Parcours de soins coordonné</span></strong> autour du <span class=\"kw-def\">médecin traitant</span>.</li>\n        <li><strong><span class=\"kw-def\">ALD</span></strong> (affection de longue durée) : <span class=\"kw-def\">protocole de soins</span>, exonération du ticket modérateur, prise en charge à <span class=\"kw-chiffre\">100 %</span>.</li>\n        <li><strong><span class=\"kw-def\">Éducation thérapeutique</span></strong> (<span class=\"kw-def\">ETP</span>) et <span class=\"kw-def\">plan personnalisé de soins</span>.</li>\n        <li>Mobilisation de la <span class=\"kw-def\">pluridisciplinarité</span> (médecin MPR, IDE, kinésithérapeute, ergothérapeute, psychologue, <span class=\"kw-def\">assistante sociale</span>) et des structures (<span class=\"kw-def\">SSR</span>, <span class=\"kw-def\">MDPH</span>, réseaux, HAD).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Discriminant.</strong> Le modèle de la maladie <span class=\"kw-def\">aiguë</span> (diagnostiquer → traiter → guérir) ne s'applique pas : dans la chronicité, l'objectif devient <strong>accompagner et préserver la qualité de vie</strong>, dans une logique de <span class=\"kw-def\">partenariat</span> avec le patient et son entourage.\n      </div>\n\n      <p class=\"obj-source\"><em>Objectif sans contenu dans la fiche source Notion (stub) ; complété depuis <span class=\"kw-clinique\">les</span> Collèges de MPR (7ᵉ éd. — items 118/122) et de Santé publique (parcours de soins, <span class=\"kw-def\">ALD</span>, <span class=\"kw-def\">ETP</span>).</em></p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 1 — Relation médecin-malade · 3 — Raisonnement et décision en médecine · 16 — Organisation du système de soins · 139 — Soins palliatifs - repères cliniques - organisation hospitalière et ambulatoire · 140 — Soins palliatifs 2 - accompagnement de la personne et de son entourage</em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"528463afa40e","n":119,"o":"119-1","u":"Définition","t":"Personnes vivant avec une maladie chronique et/ou en situation de handicap et leurs aidants : connaître l'expérience, le vécu et les savoirs expérientiels","q":"Comment définir un aidant (proche aidant) en lien avec la maladie chronique ou le handicap ?","a":"<p>Un aidant est une <strong>personne non professionnelle</strong> qui vient en aide de façon régulière à un proche en perte d'autonomie ou en situation de handicap, pour les <strong>activités de la vie quotidienne</strong>.</p>"},{"i":"738a34120d71","n":119,"o":"119-1","u":"Définition","t":"Personnes vivant avec une maladie chronique et/ou en situation de handicap et leurs aidants : connaître l'expérience, le vécu et les savoirs expérientiels","q":"Qu'est-ce que le savoir expérientiel et le concept de patient partenaire ?","a":"<ul><li>Le <strong>savoir expérientiel</strong> est la connaissance acquise par la personne du fait de vivre avec sa maladie au quotidien, constituant une <strong>expertise \"profane\"</strong> complémentaire du savoir médical.</li><li>Le concept de <strong>patient partenaire / patient-expert</strong> est la reconnaissance de cette expertise et la <strong>co-construction des décisions de soin</strong> avec la personne malade, s'inscrivant dans la démocratie sanitaire (droits des usagers) et étant le socle de l'<strong>éducation thérapeutique du patient (ETP)</strong>.</li></ul>"},{"i":"8222419c3df9","n":119,"o":"119-1","u":"Définition","t":"Personnes vivant avec une maladie chronique et/ou en situation de handicap et leurs aidants : connaître l'expérience, le vécu et les savoirs expérientiels","q":"Quel est le rôle des aidants et quels sont les risques associés à ce rôle ?","a":"<p>Les aidants ont un <strong>rôle central</strong>, particulièrement auprès de l'enfant et de la personne très dépendante. Cependant, ils peuvent subir le <strong>fardeau de l'aidant</strong>, c'est-à-dire un risque d'<strong>épuisement</strong>, un retentissement sur leur propre santé, leur vie sociale et financière, soulignant ainsi leurs besoins de <strong>répit, de soutien et de reconnaissance</strong>.</p>"},{"i":"ae9bd1bce261","n":119,"o":"119-1","u":"Définition","t":"Personnes vivant avec une maladie chronique et/ou en situation de handicap et leurs aidants : connaître l'expérience, le vécu et les savoirs expérientiels","q":"Qu'englobe le vécu et l'expérience de la maladie pour la personne atteinte ?","a":"<p>Le vécu et l'expérience de la maladie englobent :</p><ul><li>Un <strong>travail de deuil</strong> de l'état de santé antérieur et un bouleversement identitaire suite à l'annonce.</li><li>Le <strong>fardeau du traitement</strong> (\"burden of treatment\"), qui correspond au poids des soins, aux contraintes et à l'organisation du quotidien.</li><li>Un <strong>retentissement sur la qualité de vie</strong> (familiale, sociale, professionnelle) et un risque d'<strong>isolement</strong>.</li><li>Une <strong>trajectoire</strong> faite de phases d'équilibre, de crises et d'aggravation.</li></ul>"},{"i":"ba1896350e28","n":119,"o":"119-1","u":"Définition","t":"Personnes vivant avec une maladie chronique et/ou en situation de handicap et leurs aidants : connaître l'expérience, le vécu et les savoirs expérientiels","q":"Quelle est la définition d'une maladie chronique ?","a":"<p>Une maladie chronique est une affection évoluant sur une <strong>longue durée</strong> (souvent <strong>> 6 mois</strong>), non spontanément résolutive, ayant un <strong>retentissement sur la vie quotidienne</strong> et nécessitant une prise en charge prolongée.</p>"},{"i":"bc1da3cdd86d","n":119,"o":"119-1","u":"Définition","t":"Personnes vivant avec une maladie chronique et/ou en situation de handicap et leurs aidants : connaître l'expérience, le vécu et les savoirs expérientiels","q":"Selon la loi du 11 février 2005, comment le handicap est-il défini ?","a":"<p>Le handicap est défini comme une <strong>limitation d'activité ou une restriction de participation</strong> à la vie en société, subie dans son environnement en raison d'une <strong>altération durable</strong> d'une ou plusieurs fonctions (physique, sensorielle, mentale, cognitive, psychique) ou d'un trouble de santé invalidant.</p>"},{"i":"ecbb8e230e69","n":119,"o":"119-1","u":"Définition","t":"Personnes vivant avec une maladie chronique et/ou en situation de handicap et leurs aidants : connaître l'expérience, le vécu et les savoirs expérientiels","q":"Qu'est-ce que le modèle de la Classification Internationale du Fonctionnement, du handicap et de la santé (CIF) de l'OMS (2001) ?","a":"<p>Le modèle de la CIF est un modèle <strong>bio-psycho-social</strong> qui articule :</p><ul><li>la <strong>déficience</strong> (au niveau de l'organe)</li><li>la <strong>limitation d'activité</strong> (au niveau de la personne)</li><li>la <strong>restriction de participation</strong> (au niveau de la société)</li></ul><p>Ces trois niveaux sont en interaction avec les <strong>facteurs personnels et environnementaux</strong>.</p>"}]};